import obsidianmd from "eslint-plugin-obsidianmd";
import preferArrows from "eslint-plugin-prefer-arrow-functions";
import pluginReactHooks from "eslint-plugin-react-hooks";
import turboPlugin from "eslint-plugin-turbo";

/**
 * Obsidian community plugin store compliance gate.
 *
 * This config is deliberately NOT built on `./base.js`. That config loads
 * `eslint-plugin-only-warn`, which patches ESLint globally on import and forces
 * every rule to "warn" — which would erase the very distinction this gate
 * exists to make. Anything reported here is an error that can get the plugin
 * rejected from, or pulled off, the community store.
 *
 * Run it in its own process (see `lint:store` in apps/obsidian) so the
 * only-warn patch from a normal lint run cannot leak into it.
 */

const severityOf = (value) => (Array.isArray(value) ? value[0] : value);
const isError = (value) =>
  severityOf(value) === "error" || severityOf(value) === 2;

// obsidianmd's recommended set mixes store blockers (error) with style advice
// (warn), and pulls in general-purpose plugins that have nothing to do with
// store review. Keep only its own error-level rules.
const storeRules = {};
for (const block of obsidianmd.configs.recommended) {
  if (!block.rules) continue;
  for (const [rule, value] of Object.entries(block.rules)) {
    if (rule.startsWith("obsidianmd/") && isError(value)) {
      storeRules[rule] = value;
    }
  }
}

/** @type {import("eslint").Linter.Config[]} */
export const config = [
  { ignores: ["dist/**", "node_modules/**", "*.config.*"] },
  // Language/plugin setup from the recommended set, without its rule severities.
  ...obsidianmd.configs.recommended.filter((block) => !block.rules),
  {
    // Registered only so that existing `eslint-disable` comments naming these
    // rules don't surface as "Definition for rule ... was not found".
    plugins: { preferArrows, "react-hooks": pluginReactHooks, turboPlugin },
  },
  {
    files: ["**/*.{ts,tsx}"],
    linterOptions: { reportUnusedDisableDirectives: "off" },
    rules: {
      ...storeRules,
      // Type-aware linting already covers this, and the recommended set's
      // globals don't know about the JSX runtime.
      "no-undef": "off",
    },
  },
];
