  const ob=(await import('eslint-plugin-obsidianmd')).default;
  const sev=v=>Array.isArray(v)?v[0]:v;
  const all={};
  for(const b of ob.configs.recommended){ if(!b.rules) continue;
    for(const [r,v] of Object.entries(b.rules)) if(r.startsWith('obsidianmd/')) all[r]=sev(v); }
  const wired=new Set(Object.keys(m.storeRules));
  const warn=Object.entries(all).filter(([r,s])=>s==='warn'||s===1);
  console.log('WARN-level obsidianmd rules ('+warn.length+') — NOT wired into this branch:');
  warn.forEach(([r])=>console.log('   '+r+(wired.has(r)?'  <-- WIRED?!':'')));
});
